 const demoUsers=[{id:"demo-analyst",name:"Alex Morgan",role:"ANALYST",initials:"AM",label:"Security Analyst · L2"},{id:"demo-senior",name:"Jamie Chen",role:"SENIOR_ANALYST",initials:"JC",label:"Senior Analyst · L3"},{id:"demo-manager",name:"Sam Rivera",role:"MANAGER",initials:"SR",label:"Security Manager"},{id:"demo-admin",name:"Dana Kim",role:"ADMIN",initials:"DK",label:"Platform Admin"}];
