 const [userMenuOpen,setUserMenuOpen]=useState(false);
 const [aiStatus,setAiStatus]=useState<{provider:string;model:string;configured:boolean;mode:string}|null>(null);
 const can=(permission:string)=>{const perms:Record<string,string[]>={ANALYST:["investigation:read","investigation:write","evidence:collect","report:write","analysis:write","analysis:ai","query:generate","response:request"],SENIOR_ANALYST:["investigation:read","investigation:write","evidence:collect","report:write","report:approve","analysis:write","analysis:ai","query:generate","response:request","audit:read"],MANAGER:["investigation:read","report:write","report:approve","analysis:write","response:request","audit:read"],ADMIN:["investigation:read","investigation:write","evidence:collect","report:write","report:approve","analysis:write","analysis:ai","query:generate","response:request","environment:admin","audit:read"]};return (perms[currentUser.role]??[]).includes(permission)};
 const [page,setPage]=useState("Overview"),[incident,setIncident]=useState(incidents[0]),[tab,setTab]=useState("Overview"),[tools,setTools]=useState(initialTools),[completed,setCompleted]=useState<number[]>([0,1,2]),[saved,setSaved]=useState(false),[queries,setQueries]=useState<string[]>([]),[analysis,setAnalysis]=useState("The user John executed powershell on WIN-PC-1047 and connected to malicious IP."),[technicalFindings,setTechnicalFindings]=useState("CrowdStrike telemetry records powershell.exe, spawned by cmd.exe, with an encoded argument. Palo Alto telemetry records an outbound session to 185.199.110.153. Google Threat Intelligence returned a suspicious, low-prevalence assessment.") ,[scope,setScope]=useState("One endpoint is currently in scope. Additional host and identity pivots remain pending."),[recommendedActions,setRecommendedActions]=useState("Preserve endpoint telemetry. Validate destination reputation with a second source. Review related sign-ins and network activity before determining disposition."),[approvedValue,setApprovedValue]=useState(false),[eventIndex,setEventIndex]=useState<number|null>(null),[queryPlatform,setQueryPlatform]=useState("Splunk"),[indicator,setIndicator]=useState(incidents[0].dest),[timeRange,setTimeRange]=useState("24 hours"),[toast,setToast]=useState(""),[queryResult,setQueryResult]=useState(false),[search,setSearch]=useState(""),[mobileNav,setMobileNav]=useState(false),[modal,setModal]=useState(""),[remoteArtifacts,setRemoteArtifacts]=useState<any[]|null>(null),[remoteTimeline,setRemoteTimeline]=useState<any[]|null>(null),[opsNote,setOpsNote]=useState(""),[opsFeedback,setOpsFeedback]=useState("USEFUL"),[opsData,setOpsData]=useState<any>({notes:[],feedback:[],sla:null,audit:[],replay:[]});
 useEffect(()=>{fetch("/api/ai/status").then(r=>r.ok?r.json():null).then(data=>{if(data)setAiStatus(data)}).catch(()=>undefined)},[]);
 useEffect(()=>{const t=localStorage.getItem("nexus-tools");if(t)try{setTools(JSON.parse(t))}catch{}const c=localStorage.getItem("nexus-completed");if(c)try{setCompleted(JSON.parse(c))}catch{}const q=localStorage.getItem("nexus-queries");if(q)try{setQueries(JSON.parse(q))}catch{}},[]);
 useEffect(()=>{if(page!=="Investigations")return;fetch(`/api/investigations/${incident.id}`).then(r=>r.ok?r.json():null).then(data=>{if(data?.steps)setCompleted(data.steps.filter((step:{complete:boolean})=>step.complete).map((step:{index:number})=>step.index))}).catch(()=>undefined)},[page,incident.id]);
 useEffect(()=>{if(page==="Environments"){fetch("/api/environment").then(r=>r.ok?r.json():null).then(data=>{if(data?.tools)setTools(data.tools.filter((tool:{enabled:boolean})=>tool.enabled).map((tool:{name:string})=>tool.name))}).catch(()=>undefined)}},[page]);
 useEffect(()=>{if(page!=="Operations")return;Promise.all([fetch("/api/notes").then(r=>r.json()),fetch("/api/feedback").then(r=>r.json()),fetch("/api/analytics/sla").then(r=>r.json()),fetch(`/api/audit?incidentId=${incident.id}`).then(r=>r.json()),fetch(`/api/replay?incidentId=${incident.id}`).then(r=>r.json())]).then(([notes,feedback,sla,audit,replay])=>setOpsData({notes,feedback,sla,audit,replay})).catch(()=>undefined)},[page,incident.id]);
 useEffect(()=>{if(page!=="Investigations")return;if(tab==="Artifacts"||tab==="Evidence")fetch(`/api/evidence?incidentId=${incident.id}`).then(r=>r.ok?r.json():null).then(data=>{if(Array.isArray(data))setRemoteArtifacts(data.map((item:any)=>({name:item.label,value:item.value??"Pending collection",source:item.sourceTool??"Not collected",confidence:item.confidence?String(item.confidence).replace(/^./, (c:string)=>c.toUpperCase()):"—",icon:item.key.includes("ip")?"network":item.key.includes("user")?"user":item.key.includes("hash")?"hash":item.key.includes("process")?"host":"identity"})))}).catch(()=>undefined);if(tab==="Timeline")fetch(`/api/timeline?incidentId=${incident.id}`).then(r=>r.ok?r.json():null).then(data=>{if(Array.isArray(data))setRemoteTimeline(data.map((event:any)=>({time:new Date(event.timestamp).toISOString().slice(11,19),name:event.eventType.replaceAll("_"," "),detail:event.description,source:event.source,severity:event.severity}))) }).catch(()=>undefined);if(tab==="Analysis")fetch(`/api/analysis?incidentId=${incident.id}`).then(r=>r.ok?r.json():null).then(data=>{if(data?.summary){setAnalysis(data.summary);setTechnicalFindings(data.technicalFindings??"");setScope(data.scope??"");setRecommendedActions(data.recommendedActions??"")}}).catch(()=>undefined)},[page,tab,incident.id]);
 useEffect(()=>{localStorage.setItem("nexus-tools",JSON.stringify(tools))},[tools]);useEffect(()=>{localStorage.setItem("nexus-completed",JSON.stringify(completed))},[completed]);useEffect(()=>{localStorage.setItem("nexus-queries",JSON.stringify(queries))},[queries]);
 const [aiDrafting,setAiDrafting]=useState(false);
