 const apiFetch=(url:string,opts:RequestInit={})=>fetch(url,{...opts,headers:{...authHeaders,...(opts.headers as Record<string,string>||{})}});
 const progress=Math.round(completed.length/steps.length*100);const activeTools=useMemo(()=>Object.values(toolsByCategory).flat().filter(t=>tools.includes(t)),[tools]);
 const incidentKind=(inc:Incident)=>{const n=(inc.title+" "+inc.rule).toLowerCase();if(n.includes("powershell")||n.includes("ps-exec"))return "powershell";if(n.includes("impossible travel")||n.includes("travel"))return "impossible_travel";if(n.includes("malware")||n.includes("edr-mal"))return "malware";if(n.includes("brute force")||n.includes("auth-bf"))return "brute_force";if(n.includes("c2")||n.includes("net-c2"))return "c2";if(n.includes("exfil")||n.includes("dlp-exf"))return "exfiltration";return "generic"};
 const queryFor=(platform:string)=>{const token=indicator||incident.dest;const range=timeRange==="1 hour"?"-1h":timeRange==="7 days"?"-7d":"-24h";const kind=incidentKind(incident);if(platform==="Splunk"){if(kind==="impossible_travel")return `index=* sourcetype="azure:aad:signin" (user="${token}" OR src_ip="${token}") earliest=${range} latest=now\n| eval country=iff(isnotnull(geoip_country), geoip_country, "Unknown")\n| stats count by user, country, src_ip, _time\n| sort _time`;if(kind==="brute_force")return `index=* sourcetype="azure:aad:signin" action=failure src_ip="${token}" earliest=${range} latest=now\n| stats count as failures by user, src_ip\n| where failures > 10\n| sort -failures`;if(kind==="c2")return `index=* (src_ip="${token}" OR dest_ip="${token}") earliest=${range} latest=now\n| stats count by src_ip, dest_ip, dest_port, bytes_out\n| where bytes_out > 0\n| sort -bytes_out`;if(kind==="exfiltration")return `index=* (src_ip="${token}" OR host="${incident.host}") earliest=${range} latest=now\n| stats sum(bytes_out) as total_bytes by src_ip, dest_ip, host\n| sort -total_bytes`;if(kind==="malware")return `index=* (file_hash="${token}" OR host="${incident.host}") earliest=${range} latest=now\n| stats count by host, file_hash, process_name, parent_process\n| sort _time`;return `index=* (src_ip="${token}" OR dest_ip="${token}" OR host="${incident.host}") earliest=${range} latest=now\n| sort _time`;}if(platform==="CrowdStrike Falcon"){if(kind==="malware")return `hash.sha256:"${token}" OR host.hostname:"${incident.host}"\n| sort timestamp desc`;if(kind==="c2")return `host.hostname:"${incident.host}" AND network.remote_address:"${token}"\n| sort timestamp desc`;return `host.hostname:"${incident.host}" AND (network.remote_address:"${token}" OR process.name:"powershell.exe")\n| sort timestamp desc`;}if(platform==="Palo Alto"){if(kind==="exfiltration")return `(addr.src in ${token} or addr.src in ${incident.host}) and bytes > 1000000\n| sort receive_time desc`;if(kind==="c2")return `(addr.src in ${incident.host} and addr.dst in ${token}) and application neq "ssl"\n| sort receive_time desc`;return `(addr.src in ${token} or addr.dst in ${token})\n| sort receive_time desc`;}if(platform==="Google SecOps"){if(kind==="impossible_travel")return `metadata.event_type = "USER_LOGIN"\nAND principal.user.userid = "${token}"\nAND metadata.base_labels.key = "result" AND metadata.base_labels.value = "SUCCESS"`;if(kind==="brute_force")return `metadata.event_type = "USER_LOGIN"\nAND principal.ip = "${token}"\nAND security_result.action = "BLOCK"`;if(kind==="c2")return `metadata.event_type = "NETWORK_CONNECTION"\nAND (principal.ip = "${token}" OR target.ip = "${token}")\nAND network.application_protocol != "HTTP"`;return `metadata.event_type = "NETWORK_CONNECTION"\nAND (principal.ip = "${token}" OR target.ip = "${token}")`;}const d=range==="-1h"?"1h":range==="-7d"?"7d":"24h";if(kind==="brute_force")return `SigninLogs\n| where TimeGenerated > ago(${d})\n| where IPAddress == "${token}" and ResultType != "0"\n| summarize Failures=count() by UserPrincipalName, IPAddress\n| where Failures > 10`;if(kind==="impossible_travel")return `SigninLogs\n| where TimeGenerated > ago(${d})\n| where UserPrincipalName == "${token}"\n| project TimeGenerated, IPAddress, Location, ResultType`;return `CommonSecurityLog\n| where TimeGenerated > ago(${d})\n| where SourceIP == "${token}" or DestinationIP == "${token}"`};
 const copy=async(text:string,label="Copied to clipboard")=>{try{await navigator.clipboard.writeText(text);notify(label)}catch{notify("Clipboard access unavailable")}};
 const runQuery=async()=>{if(!can("query:generate")){notify("Your role cannot generate queries");return;}setQueryResult(true);setQueries(q=>[...q,`${queryPlatform} · ${indicator}`]);try{await apiFetch(`/api/queries/run`,{method:"POST",body:JSON.stringify({incidentId:incident.id,platform:queryPlatform,indicator,timeRange})});notify(`Mock ${queryPlatform} search returned 4 synthetic events and was persisted`)}catch{notify(`Mock ${queryPlatform} search returned 4 synthetic events`)}};
