 const checks=useMemo(()=>{const text=approvedValue?analysis.replace(/WIN-PC-1047/g,"WIN-PC-1042").replace(/malicious IP/gi,"potentially malicious IP"):analysis;return [{title:"Evidence consistency",ok:!text.includes("WIN-PC-1047"),detail:"Hostname matches collected Falcon telemetry"},{title:"Evidence language",ok:!/malicious IP/i.test(text),detail:"Use confidence-aligned threat wording"},{title:"Unsupported conclusions",ok:!/compromised|attacker/i.test(text),detail:"No unsupported compromise claim detected"},{title:"Required artifacts",ok:artifacts.filter(a=>a.value.startsWith("Pending")).length===0,detail:`${artifacts.filter(a=>a.value.startsWith("Pending")).length} artifacts remain uncollected`},{title:"Terminology",ok:!/powershell/.test(text),detail:"Use product-standard capitalization"}]},[analysis,approvedValue]);
 const filteredIncidents=incidents.filter(i=>(`${i.id} ${i.title} ${i.host} ${i.user}`).toLowerCase().includes(search.toLowerCase())); const displayArtifacts=remoteArtifacts??artifacts; const displayTimeline=remoteTimeline??timeline;
